<?php
declare(strict_types=1);
require_once __DIR__ . '/app.php';

function posted(string $name, int $max=12000): string {
    $value = trim((string)($_POST[$name] ?? ''));
    if (mb_strlen($value) > $max) throw new RuntimeException('One of the form fields is too long.');
    return $value;
}
function required_value(string $name, string $label, int $max=12000): string {
    $value=posted($name,$max); if ($value==='') throw new RuntimeException($label.' is required.'); return $value;
}
function action_target(): string {
    $ref = $_SERVER['HTTP_REFERER'] ?? '/dashboard';
    $path = parse_url($ref,PHP_URL_PATH) ?: '/dashboard';
    $query = parse_url($ref,PHP_URL_QUERY);
    $out = safe_return_path($path);
    if ($query) $out .= '?'.$query;
    return $out;
}
function set_status(string $table, int $id, string $from, string $to, int $actorId, string $note=''): void {
    $allowed=['motions','petitions','sittings','vote_subjects','committees','committee_meetings'];
    if (!in_array($table,$allowed,true)) throw new RuntimeException('Unsupported record type.');
    $q=db()->prepare("SELECT status FROM {$table} WHERE id=?"); $q->execute([$id]); $old=$q->fetchColumn();
    if (!$old || $old!==$from) throw new RuntimeException('This record has changed or is no longer at that review stage. Reload and try again.');
    $hasUpdatedAt = in_array($table, ['motions','petitions','sittings','vote_subjects','committees'], true);
    $sql = $hasUpdatedAt
        ? "UPDATE {$table} SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status=?"
        : "UPDATE {$table} SET status=? WHERE id=? AND status=?";
    $q=db()->prepare($sql);
    $q->execute([$to,$id,$from]); if ($q->rowCount()!==1) throw new RuntimeException('The record could not be updated.');
    audit($actorId,'status_change',rtrim($table,'s'),$id,status_label($from).' → '.status_label($to).($note!==''?' — '.$note:''));
}
function require_post_role(array $user, array $roles): void { require_role($user,$roles); }
function send_reset_email(string $email,string $token): bool {
    $from=env_value('EBUNGE_MAIL_FROM'); $base=env_value('EBUNGE_PUBLIC_URL');
    if (!$from || !$base) return false;
    $link=rtrim($base,'/').'/reset-password?token='.rawurlencode($token);
    $subject='Reset your e-Bunge password';
    $message="A password reset was requested for your e-Bunge account. Open this one-time link within one hour:\n\n{$link}\n\nIf you did not request this, ignore this message.";
    return mail($email,$subject,$message,'From: '.$from."\r\nContent-Type: text/plain; charset=UTF-8");
}
function login_user(array $user,bool $remember): void {
    session_regenerate_id(true); $_SESSION['user_id']=(int)$user['id']; $_SESSION['csrf']=bin2hex(random_bytes(32));
    if ($remember) {
        $selector=bin2hex(random_bytes(8)); $validator=bin2hex(random_bytes(32)); $expiry=time()+30*86400;
        $q=db()->prepare('INSERT INTO remember_tokens(selector,user_id,token_hash,expires_at) VALUES(?,?,?,?)'); $q->execute([$selector,$user['id'],hash('sha256',$validator),$expiry]);
        setcookie('ebunge_remember',$selector.':'.$validator,cookie_options($expiry));
    }
}
